-- T05 core schema.
--
-- All application tables live in the nonexposed `app` schema, per T00: "Application
-- tables remain in a nonexposed schema." Nothing here is granted to `anon` or
-- `authenticated`; the API reaches these tables with a server-side role only, and
-- the browser never writes to them directly.
--
-- SQL names are snake_case; the wire contract is camelCase. Mapping happens in
-- apps/api/src/core/mapping.ts, never by leaking column names outward.
--
-- IDs are supplied by the caller (capture sends reelId and attachmentIds) or
-- generated by the API in Node. No uuid-generating extension is required, so this
-- migration applies to a bare database.

create schema if not exists app;

-- ── Allowlisted users ────────────────────────────────────────────────────────
-- Exactly two product users with equal access. Rows are provisioned, never
-- self-registered; there is no public signup.
create table if not exists app.users (
  id          uuid primary key,
  name        text not null unique check (name in ('NOXAVA', 'SZRON')),
  avatar_url  text
);

-- ── Shared meme library ──────────────────────────────────────────────────────
-- Present so an existing association can be stored and validated. T05 implements
-- no library management routes; that is a later task.
create table if not exists app.memes (
  id            uuid primary key,
  name          text not null,
  thumbnail_ref text,
  asset_ref     text not null
);

-- ── Reels ────────────────────────────────────────────────────────────────────
create table if not exists app.reels (
  id                      uuid primary key,
  -- Monotonic, bumped by every accepted mutation. Compare-and-update uses it.
  version                 integer not null default 1 check (version >= 1),
  title                   text not null default '',
  status                  text not null default 'idea'
                            check (status in ('idea', 'to_record', 'editing', 'ready', 'published')),
  priority                text not null default 'normal'
                            check (priority in ('urgent', 'normal', 'evergreen')),
  input_note              text not null default '',
  -- Immutable original capture. Excluded from the scalar PATCH allowlist.
  original_input          jsonb not null,
  script                  text not null default '',
  editing_notes           text not null default '',
  editor_id               uuid references app.users (id),
  -- ExportReference, revision included. Replacement increments that revision even
  -- when the URL or file id is unchanged.
  current_export          jsonb,
  verification            jsonb,
  programme_state         text not null default 'unchecked'
                            check (programme_state in ('unchecked', 'matched', 'no_match')),
  programme_attachment    jsonb,
  programme_input_hash    text,
  programme_document_version_id uuid,
  kdrive_folder           jsonb,
  -- Set when entering `editing` from another status; never reset by re-saving
  -- editing, nor by priority or editor changes.
  editing_started_at      timestamptz,
  published_at            timestamptz,
  publication_urls        text[] not null default '{}',
  publication_description text not null default '',
  publication_hashtags    text not null default '',
  -- Required production deliverable. Defaults false, including for offline and
  -- share capture; never inferred from an export or attachment.
  feed_cover_done         boolean not null default false,
  created_by              uuid not null references app.users (id),
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  deleted_at              timestamptz,
  -- A verification record only makes sense alongside an export.
  constraint reels_verification_requires_export
    check (verification is null or current_export is not null)
);

-- Supports the product list order (priority, then newest) and keyset paging.
-- The priority rank is an expression index, so it needs its own parentheses.
create index if not exists reels_list_order_idx
  on app.reels (
    (case priority when 'urgent' then 0 when 'normal' then 1 else 2 end),
    created_at desc,
    id
  )
  where deleted_at is null;

create index if not exists reels_status_idx on app.reels (status) where deleted_at is null;

-- ── Persistent hook shortlist ────────────────────────────────────────────────
-- A Reel has zero or more active hooks. There is no singular authoritative hook
-- field and no use-hook endpoint. `source` and `created_at` are server-owned
-- provenance: editing wording never manufactures a new generation history.
create table if not exists app.reel_hooks (
  id         uuid primary key,
  reel_id    uuid not null references app.reels (id) on delete cascade,
  text       text not null,
  source     text not null check (source in ('user', 'ai')),
  position   integer not null check (position >= 0),
  created_at timestamptz not null default now(),
  -- Deferred so a transaction can shift positions when inserting in the middle
  -- without tripping the constraint mid-statement.
  constraint reel_hooks_unique_position unique (reel_id, position) deferrable initially immediate
);

create index if not exists reel_hooks_reel_idx on app.reel_hooks (reel_id, position);

-- ── Attachments ──────────────────────────────────────────────────────────────
-- Capture creates image rows as `pending`; the ordinary initiate/complete
-- lifecycle transfers them. Completion is validated server-side, never accepted
-- on a client assertion alone.
create table if not exists app.attachments (
  id           uuid primary key,
  reel_id      uuid not null references app.reels (id) on delete cascade,
  purpose      text not null check (purpose in ('input', 'source', 'material')),
  kind         text not null check (kind in ('url', 'image')),
  label        text not null default '',
  url          text,
  storage_key  text,
  state        text not null default 'pending' check (state in ('pending', 'ready', 'failed')),
  file_name    text,
  mime_type    text,
  byte_size    bigint check (byte_size is null or byte_size >= 0),
  -- Server-observed size at completion. Distinct from the client's declared
  -- byte_size so a mismatch is detectable rather than assumed away.
  stored_byte_size bigint check (stored_byte_size is null or stored_byte_size >= 0),
  created_at   timestamptz not null default now(),
  completed_at timestamptz,
  constraint attachments_ready_requires_storage
    check (state <> 'ready' or storage_key is not null)
);

create index if not exists attachments_reel_idx on app.attachments (reel_id);

-- ── Reel ↔ meme associations ─────────────────────────────────────────────────
create table if not exists app.reel_memes (
  reel_id     uuid not null references app.reels (id) on delete cascade,
  meme_id     uuid not null references app.memes (id),
  attached_at timestamptz not null default now(),
  primary key (reel_id, meme_id)
);

-- ── Idempotency ledger ───────────────────────────────────────────────────────
-- Written in the same transaction as the domain change. The same operation with
-- the same payload replays its original result, including after later edits; the
-- same id with a different payload is IDEMPOTENCY_CONFLICT.
create table if not exists app.operations (
  operation_id uuid primary key,
  actor_id     uuid not null references app.users (id),
  route        text not null,
  payload_hash text not null,
  result       jsonb not null,
  created_at   timestamptz not null default now()
);
